public class Solution {
    static class Point {
        protected int x, y;
        public Point(int x, int y) { this.x = x; this.y = y; }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false; // Symmetry guard
            Point p = (Point) o;
            return x == p.x && y == p.y;
        }
    }

    static class ColoredPoint extends Point {
        private String color;
        public ColoredPoint(int x, int y, String color) {
            super(x, y);
            this.color = color;
        }
        @Override public boolean equals(Object o) {
            if (!super.equals(o)) return false;
            ColoredPoint cp = (ColoredPoint) o;
            return color.equals(cp.color);
        }
    }

    public static void main(String[] args) {
        Point p = new Point(1, 2);
        ColoredPoint cp = new ColoredPoint(1, 2, "Red");
        System.out.println("p.equals(cp):  " + p.equals(cp));
        System.out.println("cp.equals(p):  " + cp.equals(p));
        System.out.println("Symmetry preserved: " + (p.equals(cp) == cp.equals(p)));
    }
}

