import java.util.ArrayList;
import java.util.List;

public class Solution {
    // Composition encapsulates the internal list and enforces LIFO rules
    static class SafeStack {
        private final List<Integer> storage = new ArrayList<>();
        public void push(int item) { storage.add(item); }
        public int pop() {
            if (storage.isEmpty()) throw new IllegalStateException("Stack empty");
            return storage.remove(storage.size() - 1);
        }
        public int peek() {
            if (storage.isEmpty()) throw new IllegalStateException("Stack empty");
            return storage.get(storage.size() - 1);
        }
    }

    public static void main(String[] args) {
        SafeStack stack = new SafeStack();
        stack.push(10);
        stack.push(20);
        System.out.println("Popped top element: " + stack.pop());
        System.out.println("Peeked current top: " + stack.peek());
    }
}

