public class Solution {
    interface Visitor {
        void visit(TextElement t);
        void visit(ImageElement i);
    }

    interface Element {
        void accept(Visitor v);
    }

    static class TextElement implements Element {
        public void accept(Visitor v) { v.visit(this); }
    }

    static class ImageElement implements Element {
        public void accept(Visitor v) { v.visit(this); }
    }

    static class ExportVisitor implements Visitor {
        public void visit(TextElement t) { System.out.println("Exporting text element"); }
        public void visit(ImageElement i) { System.out.println("Exporting image element"); }
    }

    public static void main(String[] args) {
        Element[] elements = { new TextElement(), new ImageElement() };
        Visitor visitor = new ExportVisitor();
        for (Element e : elements) {
            e.accept(visitor); // Double dispatch executed
        }
    }
}

import java.util.HashMap;
import java.util.Map;

public class Solution {
    static class EmulatedObject {
        protected Map<String, Runnable> vtable = new HashMap<>();
        public EmulatedObject() {
            vtable.put("sayHello", () -> System.out.println("Parent vtable implementation"));
        }
        public void invoke(String method) {
            Runnable target = vtable.get(method);
            if (target != null) target.run();
        }
    }

    static class EmulatedChild extends EmulatedObject {
        public EmulatedChild() {
            super();
            // Overwrite vtable slot for overridden method
            vtable.put("sayHello", () -> System.out.println("Child overridden vtable implementation"));
        }
    }

    public static void main(String[] args) {
        EmulatedObject obj = new EmulatedChild();
        obj.invoke("sayHello");
    }
}

public class Solution {
    interface Alpha {
        default void ping() {
            System.out.println("Alpha default ping");
        }
    }

    interface Beta {
        default void ping() {
            System.out.println("Beta default ping");
        }
    }

    static class ServiceNode implements Alpha, Beta {
        @Override
        public void ping() {
            // Explicitly resolve collision by selecting Alpha's default implementation
            Alpha.super.ping();
            System.out.println("ServiceNode custom ping");
        }
    }

    public static void main(String[] args) {
        ServiceNode node = new ServiceNode();
        node.ping();
    }
}

public class Solution {
    static abstract class Plugin {
        // Template method enforcing execution sequence
        public final void run() {
            init();
            executeTask();
            teardown();
        }

        protected void init() {
            System.out.println("Plugin initialized");
        }

        protected abstract void executeTask();

        protected void teardown() {
            System.out.println("Plugin cleaned up");
        }
    }

    static class DatabasePlugin extends Plugin {
        @Override
        protected void executeTask() {
            System.out.println("Executing database synchronization task");
        }
    }

    public static void main(String[] args) {
        Plugin plugin = new DatabasePlugin();
        plugin.run();
    }
}
